import { familySharedBody } from "./prompt.ts";
import { parseModelRef } from "./resolve.ts";
import { matchesModel } from "./routing.ts";
import type { HarnessRouteModel } from "./routing.ts";

export type PromptFamily = "codex" | "grok-build" | "zcode" | "qwen-code" | "deepseek" | "pi-default";

export interface PromptFamilyRoute {
	match: readonly string[];
	family: PromptFamily;
}

export interface PromptFamilyConfig {
	named?: PromptFamily;
	routes?: readonly PromptFamilyRoute[];
}

export const DEFAULT_PROMPT_FAMILY_ROUTES = [
	{
		match: ["openai/*", "openai-codex/*", "*/openai/*", "*/openai-codex/*", "gpt-*"],
		family: "codex",
	},
	{
		match: ["xai/*", "x-ai/*", "*/xai/*", "*/x-ai/*", "grok-*"],
		family: "grok-build",
	},
	{
		match: ["z-ai/*", "zai/*", "*/z-ai/*", "*/zai/*", "glm-*"],
		family: "zcode",
	},
	{
		match: ["qwen/*", "alibaba/*", "dashscope/*", "*/qwen/*", "*/alibaba/*", "qwen*", "qwq-*"],
		family: "qwen-code",
	},
	{
		match: ["deepseek/*", "deepseek-ai/*", "*/deepseek/*", "*/deepseek-ai/*", "deepseek-*"],
		family: "deepseek",
	},
] as const satisfies readonly PromptFamilyRoute[];

export function parsePromptFamily(value: unknown): PromptFamily | undefined {
	return value === "codex" || value === "grok-build" || value === "zcode" || value === "qwen-code"
		|| value === "deepseek" || value === "pi-default"
		? value
		: undefined;
}

export function modelRefFromSpec(spec: string | undefined): HarnessRouteModel | undefined {
	if (!spec?.trim()) return undefined;
	return parseModelRef(spec.trim());
}

/** Child prompt family from the resolved model. Does not use parent usage or DEFAULT_HARNESS. */
export function routePromptFamilyForModel(
	model: HarnessRouteModel | undefined,
	config: PromptFamilyConfig = {},
): PromptFamily {
	if (config.named) return config.named;
	if (!model) return "pi-default";
	for (const route of [...(config.routes ?? []), ...DEFAULT_PROMPT_FAMILY_ROUTES]) {
		if (route.match.some((pattern) => matchesModel(pattern, model))) return route.family;
	}
	return "pi-default";
}

export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.includesFamilyShared || input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files: rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`],
	};
}
