edits.newText:
export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	const withCommon = (text: string, files: string[]) => {
		if (!input.common || input.family === "pi-default") return { text, files };
		const common = commonBody(input.root).trim();
		if (!common || text.endsWith(common)) return { text, files };
		return {
			text: [text, common].filter(Boolean).join("\n"),
			files: [...files, "common.md"],
		};
	};
	if (input.includesFamilyShared || input.family === "pi-default") {
		const result = withCommon(rolePrompt, rolePrompt ? ["role"] : []);
		return { family: input.family, ...result };
	}
	const shared = familySharedBody(input.family, input.root).trim();
	if (!shared) {
		const result = withCommon(rolePrompt, rolePrompt ? ["role"] : []);
		return { family: input.family, ...result };
	}
	if (rolePrompt.includes(shared)) {
		const result = withCommon(rolePrompt, [`${input.family}/shared.md`, "role"]);
		return { family: input.family, ...result };
	}
	const text = [shared, rolePrompt].filter(Boolean).join("\n");
	const files = rolePrompt ? [`${input.family}/shared.md`, "role"] : [`${input.family}/shared.md`];
	const result = withCommon(text, files);
	return { family: input.family, ...result };
}

